'use strict';
/* ホーム画面合体パズル【フォルダ版】 — 画面側。ルールは engine.js
 * (window.HomeMerge) に集約。
 * このブランチでは合体数（強化数）を廃止し、「重ねる」=フォルダ化：
 * - ドラッグで重ねてすぐ離す → 入れ替え（対象がドラッグ元へ滑って避ける）。
 *   重ねたまま約0.5秒ホールドすると「重ねる」プレビューに切り替わり
 *   （対象の背面にフォルダ風の台座が開き、対象が少し大きくなり、持っている
 *   アイコンは吸い付くように少し縮む）、離すとフォルダができる／収納される。
 *   カテゴリ条件に合わないフォルダの上では切り替わらない。
 * - フォルダもドラッグで動かせる（周囲8マスへ1マス。アイコン／フォルダと
 *   位置交換になり、1手として数える）。ただしフォルダが動いてアイコンを
 *   取り込むことはしない。条件に合わないアイコンをフォルダに重ねても、
 *   収納されず入れ替えになる。フォルダをタップすると開く画面が出て、
 *   中身をタップするとそのアイコンが周囲の空きマスへ出る。
 * - タップ移動ではフォルダ化しない（入れ替え・移動のみの自動判定）。
 * 区別は文字ではなく「提示」だけで伝える（2026-11-10 ユーザー指定
 * 「定義じゃなくて提示」、実機のホーム画面に準拠）。
 * 操作の意図（intent）は画面側が決め、エンジン（simulateMove / applyMove）が
 * それを受けて結果を計算する。
 * 反抗アイコンは持った瞬間に発動し、ランダムな位置へ移動する。
 * クリア時は、実際のスマホのバッテリー切れのように画面が真っ黒になる演出のあと、
 * お祝い表示と再起動ボタンを出す。
 */
(function () {
  const E = window.HomeMerge;
  const boardEl = document.getElementById('board');
  const batteryFill = document.getElementById('batteryFill');
  const batteryText = document.getElementById('batteryText');
  const clockText = document.getElementById('clockText');
  const statusText = document.getElementById('statusText');
  // 時刻は端末の時計にそのまま合わせる（ブラウザの Date は端末のローカル時刻）。
  // 実際のスマホのステータスバーと同じで、手動の時刻設定は持たない
  function updateClock() {
    const d = new Date();
    clockText.textContent = `${d.getHours()}:${String(d.getMinutes()).padStart(2, '0')}`;
  }
  updateClock();
  setInterval(updateClock, 1000);
  const winOverlay = document.getElementById('winOverlay');
  const restartBtn = document.getElementById('restartBtn');

  const REBEL_MARK = '<svg class="rebel-mark" viewBox="0 0 16 16" aria-hidden="true"><path d="M2 5h3V2m6 0v3h3m0 6h-3v3m-6 0v-3H2"/></svg>';
  // 反抗の目（ごきげんサバイバルの iconArtwork と同じパス）
  const REBEL_EYE_PATH = 'M3 1.5C5 3 7.6 5 9.1 6.8C10.9 9 8.5 12.5 6.4 12.5C3.4 12.5 2.4 9.1 3 1.5Z';
  const REBEL_EYE = `<path d="${REBEL_EYE_PATH}" transform="translate(1.6 1.75) scale(.75)"/>`;
  const REBEL_EYE_MIRRORED = `<g transform="translate(25 0) scale(-1 1)">${REBEL_EYE}</g>`;
  const REBEL_EYES = `${REBEL_EYE}${REBEL_EYE_MIRRORED}`;

  let state = E.createGame();
  let drag = null; // { iconId, fromX, fromY, startX, startY, active, ghost, dests, target, targetKey, intent, phase }
  let press = null; // タップ判定用: { pointerId, cell, handled }
  let tapSel = null; // タップ操作で選択中のアイコンID
  let openFolderId = null; // 開いているフォルダ画面のフォルダID
  let winShown = false;   // クリア演出を出したか
  let winTimers = [];     // クリア演出のタイマー
  // （反抗アイコンは持った瞬間に発動するので、タップ判定待ちの状態は持たない）

  // 機嫌の表記は、ごきげんサバイバルの MOODS と同じ
  const MOODS = { normal: '通常', eager: 'やる気', sleep: 'ねむり', rebel: '反抗' };
  function moodOf(icon) {
    if (icon.z > 0) return 'sleep';
    return icon.mood; // 'normal' | 'eager' | 'rebel'
  }
  function moodLabel(icon) {
    return MOODS[moodOf(icon)];
  }

  // アイコンの絵は、ごきげんサバイバルの iconArtwork（通常種・非ワープ）をコードのまま使う。
  // 顔は「矢印＋両目（反抗時は反抗の目）＋反抗マーク」で、口は存在しない。
  // ただしサヨク・ウヨクだけは片目デザイン（2026-11-10 ユーザー指定、手描きスケッチ準拠）：
  // 矢印が斜め下へ来る側の目を、眼帯に隠されたように無くし、矢印をその目に合わせる。
  // ウヨク（＼、左上と右下）は右目を無くして左目だけ、サヨク（／、右上と左下）は
  // 左目を無くして右目だけ。反抗の目も、残る側の1つだけにする
  // 矢印はフォント文字ではなく SVG で描く（2026-11-10 ユーザー指摘で変更）：
  // ⤢⤡ などのグリフはブラウザ・端末のフォント差で大きさと位置が変わってしまう
  // ため、こちらで引いた線ならどの環境でも同じ寸法になる。座標はタイル内寸法
  // （76×80、cqw と同じ物差し）で、斜めは下端が目のライン（高さ約77%）に
  // そろうように引いてある（ユーザーの手描きスケッチ準拠）
  // 矢印は全種類で同一の形（タイル内寸法 76×80 単位）：
  // - 両端フック型の直線矢印。軸の太さ 5、中心 (38,40) から ±20、先端の
  //   分岐する2本の線（腕）は 8
  // - 斜めはタテの矢印を中心まわりに 45° 回転させた形（腕は水平・垂直の
  //   L 字で 11.3）。外枠がタテ・ヨコとそろうよう先端は (18,60) と (58,20)
  //   （ウヨクは左右反転）
  const ARROW_SVGS = {
    tate: '<path d="M38 20 V60"/><path d="M30 28 L38 20 L46 28"/><path d="M30 52 L38 60 L46 52"/>',
    yoko: '<path d="M18 40 H58"/><path d="M26 32 L18 40 L26 48"/><path d="M50 32 L58 40 L50 48"/>',
    sayoku: '<path d="M18 60 L58 20"/><path d="M46.7 20 H58 V31.3"/><path d="M18 48.7 V60 H29.3"/>',
    uyoku: '<path d="M58 60 L18 20"/><path d="M29.3 20 H18 V31.3"/><path d="M58 48.7 V60 H46.7"/>',
  };
  function iconArtwork(type) {
    let eyes = '<i class="eye left"></i><i class="eye right"></i>';
    let rebelEyes = REBEL_EYES;
    if (type.id === 'uyoku') { eyes = '<i class="eye left"></i>'; rebelEyes = REBEL_EYE; }
    else if (type.id === 'sayoku') { eyes = '<i class="eye right"></i>'; rebelEyes = REBEL_EYE_MIRRORED; }
    return `<span class="arrow" role="img" aria-label="${type.arrows.join('と')}"><svg viewBox="0 0 76 80" aria-hidden="true">${ARROW_SVGS[type.id]}</svg></span><span class="face" aria-hidden="true">${eyes}<svg class="rebel-eyes" viewBox="0 0 25 14">${rebelEyes}</svg></span>${REBEL_MARK}`;
  }

  // 表示テキスト（機嫌チップ・アイコン名）は出さない（ユーザー指定）。
  // 機嫌はアイコン自体の表情・アニメーションで表れる。
  // 眠りの残量は、ごきげんサバイバルの盤面表示と同じく Z の数で表す（.sleep-marks）。
  function iconHTML(icon) {
    const type = E.TYPES[icon.type];
    const mood = moodOf(icon);
    const sleepMarks = icon.z > 0
      ? `<span class="sleep-marks" aria-hidden="true">${'<span>Z</span>'.repeat(Math.min(3, icon.z))}</span>`
      : '';
    return `<div class="icon-stack" data-icon-id="${icon.id}"><div class="app-icon ${type.colorName} ${mood} ${type.id}" style="--hop:1.6cqw">${iconArtwork(type)}${sleepMarks}</div></div>`;
  }

  function iconAtIn(icons, x, y) {
    return icons.find(i => i.x === x && i.y === y) || null;
  }

  // icons は表示に使うアイコン配列（通常は state.icons、ドラッグ中はプレビューの結果）。
  // hideId のアイコンは描かない（ドラッグ中、指に付いている側）。
  // folders も同様（省略時は state.folders）。
  function render(icons, hideId, folders) {
    folders = folders || state.folders;
    batteryFill.style.width = state.battery + '%';
    batteryFill.classList.toggle('low', state.battery <= 20);
    batteryText.textContent = state.battery + '%';
    statusText.textContent = state.status === 'won' ? 'クリア！' : state.status === 'lost' ? 'ゲームオーバー' : '';

    boardEl.innerHTML = '';
    for (let y = 0; y < state.rows; y++) {
      for (let x = 0; x < state.cols; x++) {
        const cell = document.createElement('div');
        cell.className = 'cell' + ((x + y) % 2 === 1 ? ' check' : '');
        cell.dataset.x = x;
        cell.dataset.y = y;
        if (E.isSettingsCell(x, y)) {
          // 左下の隅には設定アプリのアイコンが固定で置かれる。
          // 歯車は文字（⚙）だとフォントによって中心からずれるため、
          // 幾何学的に中心が合う SVG で描く
          const teeth = [0, 45, 90, 135, 180, 225, 270, 315]
            .map(a => `<rect x="43" y="8" width="14" height="24" rx="4" transform="rotate(${a} 50 50)"/>`).join('');
          const gearSvg = `<svg class="gear" viewBox="0 0 100 100" aria-hidden="true"><defs><mask id="gearHole"><rect width="100" height="100" fill="#fff"/><circle cx="50" cy="50" r="12" fill="#000"/></mask></defs><g fill="#fff" mask="url(#gearHole)"><circle cx="50" cy="50" r="30"/>${teeth}</g></svg>`;
          cell.innerHTML = `<div class="icon-stack"><button class="app-icon gray settings-app" type="button" aria-label="設定">${gearSvg}</button></div>`;
          boardEl.appendChild(cell);
          continue;
        }
        if (E.isSearchCell(x, y)) {
          // 設定の横には検索アプリのアイコンが固定で置かれる
          cell.innerHTML = '<div class="icon-stack"><button class="app-icon search-tile search-app" type="button" aria-label="検索"><span class="lens" aria-hidden="true">🔍</span></button></div>';
          boardEl.appendChild(cell);
          continue;
        }
        const folder = (folders || []).find(f => f.x === x && f.y === y);
        if (folder) {
          cell.appendChild(folderStackEl(folder));
          cell.title = `フォルダ（${folder.members.map(m => E.TYPES[m.type].name).join('・')}）`;
          boardEl.appendChild(cell);
          continue;
        }
        const icon = iconAtIn(icons, x, y);
        if (icon && icon.id !== hideId) {
          const holder = document.createElement('div');
          holder.innerHTML = iconHTML(icon);
          const stack = holder.firstElementChild;
          cell.appendChild(stack);
          if (tapSel === icon.id) stack.classList.add('selected');
          cell.title = `${E.TYPES[icon.type].name} ${moodLabel(icon)} 放置${icon.neglect}`;
        }
        boardEl.appendChild(cell);
      }
    }
    maybeShowWin();
  }

  // クリア演出：画面がフェードして真っ黒になり（バッテリー切れの再現）、
  // 少し置いてからお祝い表示と再起動ボタンを出す
  function maybeShowWin() {
    if (state.status !== 'won' || winShown) return;
    winShown = true;
    winOverlay.hidden = false;
    // hidden 解除直後にクラスを足すと遷移が効かないことがあるため、描画を挟む
    requestAnimationFrame(() => requestAnimationFrame(() => {
      winOverlay.classList.add('on');
    }));
    winTimers.push(setTimeout(() => winOverlay.classList.add('show-msg'), 1400));
  }

  function resetWinOverlay() {
    winTimers.forEach(t => clearTimeout(t));
    winTimers = [];
    winShown = false;
    winOverlay.classList.remove('on', 'show-msg');
    winOverlay.hidden = true;
  }

  restartBtn.addEventListener('click', () => {
    resetWinOverlay();
    if (drag) { removeGhost(); drag = null; }
    press = null;
    tapSel = null;
    state = E.createGame();
    render(state.icons, null);
  });

  // フォルダのタイル： 中身のミニアイコン（最大9個）を並べた、実機風の見た目
  function folderStackEl(folder) {
    const stack = document.createElement('div');
    stack.className = 'folder-stack';
    stack.dataset.folderId = folder.id;
    const tile = document.createElement('div');
    tile.className = 'folder-tile';
    const minis = folder.members.slice(0, 9).map(m =>
      `<div class="app-icon ${E.TYPES[m.type].colorName} normal mini">${iconArtwork(E.TYPES[m.type])}</div>`).join('');
    tile.innerHTML = `<div class="folder-minis">${minis}</div>`;
    stack.appendChild(tile);
    return stack;
  }

  // 位置が変わったアイコンが滑って移動して見えるように描き直す（FLIP）
  function flipRender(icons, hideId, folders) {
    const before = new Map();
    boardEl.querySelectorAll('.icon-stack[data-icon-id]').forEach(el => {
      before.set(el.dataset.iconId, el.getBoundingClientRect());
    });
    render(icons, hideId, folders);
    boardEl.querySelectorAll('.icon-stack[data-icon-id]').forEach(el => {
      const b = before.get(el.dataset.iconId);
      if (!b) return;
      const a = el.getBoundingClientRect();
      const dx = b.left - a.left, dy = b.top - a.top;
      if (dx === 0 && dy === 0) return;
      el.style.transition = 'none';
      el.style.transform = `translate(${dx}px, ${dy}px)`;
      el.style.zIndex = '5';
      requestAnimationFrame(() => {
        el.style.transition = 'transform 170ms ease';
        el.style.transform = '';
      });
    });
  }

  function cellFromPoint(clientX, clientY) {
    const el = document.elementFromPoint(clientX, clientY);
    const cell = el && el.closest ? el.closest('.cell') : null;
    if (!cell || !boardEl.contains(cell)) return null;
    return { x: Number(cell.dataset.x), y: Number(cell.dataset.y) };
  }

  // ポインターに一番近い候補マス（開始マス含む）を選ぶ
  function nearestTarget(clientX, clientY) {
    const rect = boardEl.getBoundingClientRect();
    const fx = (clientX - rect.left) / (rect.width / state.cols) - 0.5;
    const fy = (clientY - rect.top) / (rect.height / state.rows) - 0.5;
    let best = null, bestD = Infinity;
    const candidates = [{ x: drag.fromX, y: drag.fromY, dest: null }]
      .concat(drag.dests.map(d => ({ x: d.x, y: d.y, dest: d })));
    for (const c of candidates) {
      const dd = (c.x - fx) * (c.x - fx) + (c.y - fy) * (c.y - fy);
      if (dd < bestD) { bestD = dd; best = c; }
    }
    return best;
  }

  // ドラッグ中のプレビューを、現在の intent で描き直す
  // ドラッグ中のプレビューを描き直す（経路方式。drag.path と
  // drag.folderTarget は updateDragTarget が決める）
  // 提示は「今離したら何が起きるか」と常に一致させる：
  // - フォルダ化の待機（folderTarget あり）：土台は「経路の手前までの
  //   押し出しが済んだ盤面」で、対象だけがフォルダに入った姿で待機する。
  //   持っているアイコンはまだ入っていない（離した時点で入る）
  // - 入れ替え（path のみ）：経路に沿った押し出しの結果を見せる
  function renderDragPreview() {
    if (!drag.path.length && !drag.folderTarget) {
      flipRender(state.icons, drag.iconId, state.folders);
      return;
    }
    if (drag.folderTarget) {
      const t = drag.folderTarget;
      const base = drag.path.length
        ? E.simulatePathMove(state, drag.iconId, drag.path, {})
        : null;
      const baseIcons = base ? base.icons : state.icons;
      const baseFolders = base ? base.folders : state.folders;
      const tIcon = baseIcons.find(i => i.x === t.x && i.y === t.y);
      const tFolder = baseFolders.find(f => f.x === t.x && f.y === t.y);
      // 対象がフォルダなら既にフォルダ状態なので、そのまま待機表示。
      // 対象がアイコンなら、そのアイコンだけを収めた見かけのフォルダ
      // （表示専用・状態は変えない）で待機を示す
      const dispFolders = (!tFolder && tIcon)
        ? baseFolders.concat([{ id: '__standby__', x: t.x, y: t.y, members: [{ ...tIcon }] }])
        : baseFolders;
      flipRender(baseIcons, drag.iconId, dispFolders);
    } else {
      const sim = E.simulatePathMove(state, drag.iconId, drag.path, {});
      flipRender(sim ? sim.icons : state.icons, drag.iconId, sim ? sim.folders : state.folders);
    }
    decorateDragTarget();
    if (drag.ghost) {
      // 「重ねる」状態では、持っているアイコンが吸い付くように少し縮む
      drag.ghost.classList.toggle('sucked', !!drag.folderTarget);
    }
  }

  function renderFolderPreview() {
    const tx = drag.target ? drag.target.x : null;
    const ty = drag.target ? drag.target.y : null;
    let icons = state.icons;
    if (drag.target) {
      const icon = icons.find(i => i.x === tx && i.y === ty);
      if (icon) icons = icons.map(i => (i.id === icon.id ? { ...i, x: drag.fromX, y: drag.fromY } : i));
    }
    const folders = [];
    for (const f0 of state.folders) {
      // 持っているフォルダ自身は盤面に描かない（アイコン版で hideId に
      // 相当）。指に付いたゴーストが実物で、盤面にも描くと二重像に
      // なり「残像」に見える（2026-11-10 ユーザー報告）
      if (f0.id === drag.folderId) continue;
      if (drag.target && f0.x === tx && f0.y === ty) {
        folders.push({ ...f0, x: drag.fromX, y: drag.fromY });
      } else folders.push(f0);
    }
    flipRender(icons, null, folders);
  }

  // アイコンのドラッグ先の決め方（2026-11-10 ユーザー指示の挿入方式）：
  // 行き先は「マス」ではなく「アイコンの間」。対象マスの中心付近だけが
  // 「上に重ねた」扱いでフォルダの待機に入り、それ以外（中心より手前／
  // 先）は「間」への挿入として、中心を過ぎたマス／手前のマスが着地点に
  // なる。例：123 の並びで 1 を 2 の位置にしたいなら、2 と 3 の間
  // （2 の中心を過ぎたあたり）に持ってくる。2 はドラッグ元側へ押し出
  // され、1 が 2 のマスに入る
  // 対象マスの中心からこの範囲（マス単位・半径）が「上に重ねた」
  const FOLDER_ZONE = 0.25;

  // 挿入／フォルダ化の計画をポインタ位置から決める（経路方式）。
  // 2026-11-10 ユーザー訂正「ドラッグ中はドラッグしてるアイコンのみ
  // その方向に縛られる」：動かしているアイコンは自分の方向のライン上
  // だけを進む。入れ替わる相手は自分の方向に縛られない（経路に沿って
  // そのまま押し出される。例：斜めに押されたヨコは斜めへずれる）。
  // 目標は「指の位置に最も近い、自分のライン上のマス」。進み方の規則
  // （次のマス W について）:
  // - W が目標のマスで、重ねられる相手がいて、ポインタが W の中心付近
  //   （半径 FOLDER_ZONE 以内）→ フォルダ化の待機（W へは進まない）
  // - W にアイコン（または収納できるフォルダ）がある → 中心を過ぎたら進む
  // - W が空き（または収納できないフォルダ）→ 半分過ぎたら進む
  function computeDragPlan(clientX, clientY) {
    const rect = boardEl.getBoundingClientRect();
    const none = { path: [], folderTarget: null };
    if (rect.width === 0) return none;
    const fx = (clientX - rect.left) / (rect.width / state.cols) - 0.5;
    const fy = (clientY - rect.top) / (rect.height / state.rows) - 0.5;
    const draggedIcon = state.icons.find(i => i.id === drag.iconId);
    if (!draggedIcon) return none;
    const origin = { x: drag.fromX, y: drag.fromY };
    // 自分の方向のライン上のマスから、指に最も近いものを目標にする
    let best = null;
    for (const dir of E.TYPES[draggedIcon.type].dirs) {
      for (let k = 1; k < 40; k++) {
        const cx = origin.x + dir[0] * k, cy = origin.y + dir[1] * k;
        if (cx < 0 || cy < 0 || cx >= state.cols || cy >= state.rows) break;
        if (E.isReservedCell(cx, cy)) break;
        const d = (cx - fx) * (cx - fx) + (cy - fy) * (cy - fy);
        if (!best || d < best.d) best = { d, dir, x: cx, y: cy };
      }
    }
    if (!best) return none;
    const px = best.x, py = best.y, dir = best.dir;
    const path = [];
    let v = { ...origin };
    let guard = 0;
    while ((v.x !== px || v.y !== py) && guard++ < 40) {
      const sim = path.length ? E.simulatePathMove(state, drag.iconId, path, {}) : null;
      const vIcons = sim ? sim.icons : state.icons;
      const vFolders = sim ? sim.folders : state.folders;
      const w = { x: v.x + dir[0], y: v.y + dir[1] };
      const occIcon = vIcons.find(i => i.id !== drag.iconId && i.x === w.x && i.y === w.y);
      const occFolder = vFolders.find(f => f.x === w.x && f.y === w.y);
      const storable = occFolder ? E.canStore(occFolder, draggedIcon.type) : false;
      const isLast = w.x === px && w.y === py;
      if (isLast && Math.hypot(fx - w.x, fy - w.y) <= FOLDER_ZONE && (occIcon || storable)) {
        return { path, folderTarget: w };
      }
      const axisLen = Math.hypot(dir[0], dir[1]);
      const prog = ((fx - v.x) * dir[0] + (fy - v.y) * dir[1]) / axisLen;
      const stepAt = (occIcon || storable) ? axisLen : axisLen / 2;
      if (prog <= stepAt) break;
      path.push(w);
      v = w;
    }
    return { path, folderTarget: null };
  }

  function updateDragTarget(clientX, clientY) {
    if (drag.kind === 'folder') {
      const near = nearestTarget(clientX, clientY);
      const key = near.dest ? `${near.dest.x},${near.dest.y}` : 'start';
      // 対象が変わったときだけ描き直す（アイコン版と同じ）。毎 move で
      // 盤面を再構築すると、滑走中アイコンの実測位置がずれて蓄積し、
      // 表示が崩れる・残像が出る原因になる（2026-11-10 ユーザー報告）
      if (drag.targetKey === key) return;
      drag.targetKey = key;
      drag.target = near.dest;
      renderFolderPreview();
      return;
    }
    const plan = computeDragPlan(clientX, clientY);
    const landing = plan.folderTarget || plan.path[plan.path.length - 1] || null;
    const key = plan.folderTarget
      ? `F${plan.folderTarget.x},${plan.folderTarget.y}|${plan.path.map(c => c.x + ',' + c.y).join(';')}`
      : (plan.path.length ? `P${plan.path.map(c => c.x + ',' + c.y).join(';')}` : 'start');
    if (drag.targetKey === key) return;
    drag.targetKey = key;
    drag.path = plan.path;
    drag.folderTarget = plan.folderTarget;
    drag.target = landing;
    drag.phase = plan.folderTarget ? 'standby' : (plan.path.length ? 'swap' : null);
    drag.intent = plan.folderTarget ? 'merge' : 'swap';
    renderDragPreview();
  }

  // 「重ねる」の開始条件は updateDragTarget（computeDragPlan）が決める：
  // 重ねられる相手の中心付近に重ねた段階で待機に入る（静止は条件に
  // しない）。待機の提示と確定／キャンセルの意味は renderDragPreview と
  // finishPointer のコメントを参照（2026-11-10 ユーザー最終仕様）

  // 「重ねる」対象のマスに台座を描く（対象マスへの装飾）
  function decorateDragTarget() {
    if (!drag || !drag.target) return;
    if (drag.intent !== 'merge') return;
    const cell = boardEl.querySelector(`.cell[data-x="${drag.target.x}"][data-y="${drag.target.y}"]`);
    if (!cell) return;
    const pedestal = document.createElement('div');
    pedestal.className = 'merge-pedestal open';
    cell.insertBefore(pedestal, cell.firstChild);
    cell.classList.add('merge-target');
  }

  // ゴーストは残らず消す（過去の取り残しも含めて全部）
  function removeGhost() {
    document.querySelectorAll('.drag-ghost').forEach(g => g.remove());
    if (drag) drag.ghost = null;
  }

  // ドラッグを中断して盤面を元の表示に戻す（異常終了時の後始末）
  function cancelDrag() {
    const wasActive = drag && drag.active;
    removeGhost();
    drag = null;
    press = null;
    if (wasActive) flipRender(state.icons, null);
  }

  boardEl.addEventListener('pointerdown', (e) => {
    if (state.status !== 'playing') return;
    // ドラッグ中の追加の押下は無視する。
    // マウスの右ボタンなど、主ボタン以外もドラッグ開始に使わない
    // （右クリック併用でドラッグ状態が壊れる不具合の対策）
    if (drag) return;
    if (!e.isPrimary) return;
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    removeGhost(); // 取り残しの掃除
    const pos = cellFromPoint(e.clientX, e.clientY);
    if (!pos) return;
    // タップ判定用に押下を記録する（ドラッグにならなかった場合に使う）
    press = { pointerId: e.pointerId, cell: pos, handled: false };
    const icon = E.iconAt(state, pos.x, pos.y);
    if (!icon) {
      // フォルダはドラッグで動かせる（スマホ準拠。2026-11-10 ユーザー訂正）。
      // 動かさずに離せばタップとして、開くフロー（handleTap）へ回る
      const folder = E.folderAt(state, pos.x, pos.y);
      if (!folder) return;
      drag = {
        kind: 'folder', folderId: folder.id, fromX: pos.x, fromY: pos.y,
        startX: e.clientX, startY: e.clientY, pointerId: e.pointerId,
        active: false, ghost: null,
        dests: E.destinationsForFolder(state, folder.id),
        target: null, targetKey: 'start',
        intent: 'swap',
      };
      try { boardEl.setPointerCapture(e.pointerId); } catch (_) { /* noop */ }
      e.preventDefault();
      return;
    }
    if (icon.z > 0) return;
    if (icon.mood === 'rebel') {
      // 反抗アイコンはドラッグで持てるが、持った瞬間にランダムな位置へ
      // 逃げてしまう（2026-11-09 ユーザー指定）。その場で発動し、ドラッグは始まらない
      press.handled = true;
      tapSel = null;
      E.applyRebelMove(state, icon.id);
      render(state.icons, null);
      return;
    }
    // 入れ替えは自分の方向に縛られない（経路方式）ため、移動候補（方向の
    // レイ）が無くてもドラッグは開始できる。到達可能性は計画側が決める
    drag = {
      kind: 'icon', iconId: icon.id, fromX: pos.x, fromY: pos.y,
      startX: e.clientX, startY: e.clientY, pointerId: e.pointerId,
      active: false, ghost: null, path: [], folderTarget: null,
      target: null, targetKey: 'start',
      intent: 'swap', phase: null,
    };
    // タップ選択はここでは消さない（離したときにタップとして処理するため）。
    // 実際にドラッグが始まった時点で、pointermove 側で選択を解除する
    try { boardEl.setPointerCapture(e.pointerId); } catch (_) { /* noop */ }
    e.preventDefault();
  });

  boardEl.addEventListener('pointermove', (e) => {
    if (!drag || e.pointerId !== drag.pointerId) return;
    const dx = e.clientX - drag.startX;
    const dy = e.clientY - drag.startY;
    if (!drag.active) {
      if (Math.hypot(dx, dy) < 8) return;
      drag.active = true;
      tapSel = null; // ドラッグが始まったらタップ選択は解除する
      // ゴーストは盤面のアイコン／フォルダそのもののコピーにして、大きさが
      // 変わらないようにする。盤面用サイズはマス基準（cqw）で決まっているため、
      // 実測したピクセル値を写す
      const isFolder = drag.kind === 'folder';
      const srcStack = boardEl.querySelector(isFolder
        ? `.folder-stack[data-folder-id="${drag.folderId}"]`
        : `.icon-stack[data-icon-id="${drag.iconId}"]`);
      const ghost = document.createElement('div');
      ghost.className = 'drag-ghost';
      if (srcStack) {
        const stackRect = srcStack.getBoundingClientRect();
        const clone = srcStack.cloneNode(true);
        clone.style.transform = '';
        clone.style.transition = '';
        clone.style.width = stackRect.width + 'px';
        clone.style.height = stackRect.height + 'px';
        clone.style.containerType = 'size'; // ゴースト内でも cqw が盤面と同じ基準になるように
        if (!isFolder) {
          const srcIcon = srcStack.querySelector('.app-icon');
          const iconRect = srcIcon.getBoundingClientRect();
          const cIcon = clone.querySelector('.app-icon');
          cIcon.style.width = iconRect.width + 'px';
          cIcon.style.height = iconRect.height + 'px';
          cIcon.style.borderRadius = getComputedStyle(srcIcon).borderRadius;
          cIcon.style.animation = 'none';
          const srcArrow = srcIcon.querySelector('.arrow');
          const cArrow = cIcon.querySelector('.arrow');
          if (srcArrow && cArrow) cArrow.style.fontSize = getComputedStyle(srcArrow).fontSize;
        } else {
          // フォルダのミニアイコンは cqw 基準なので、実測ピクセルを写す
          const srcTile = srcStack.querySelector('.folder-tile');
          const cTile = clone.querySelector('.folder-tile');
          if (srcTile && cTile) {
            const tileRect = srcTile.getBoundingClientRect();
            cTile.style.width = tileRect.width + 'px';
            cTile.style.height = tileRect.height + 'px';
            cTile.style.borderRadius = getComputedStyle(srcTile).borderRadius;
          }
          const srcMinis = srcStack.querySelectorAll('.app-icon.mini');
          clone.querySelectorAll('.app-icon.mini').forEach((cMini, i) => {
            const sMini = srcMinis[i];
            if (!sMini) return;
            const r = sMini.getBoundingClientRect();
            cMini.style.width = r.width + 'px';
            cMini.style.height = r.height + 'px';
            cMini.style.borderRadius = getComputedStyle(sMini).borderRadius;
            const sArrow = sMini.querySelector('.arrow');
            const cArrow = cMini.querySelector('.arrow');
            if (sArrow && cArrow) cArrow.style.fontSize = getComputedStyle(sArrow).fontSize;
          });
        }
        ghost.appendChild(clone);
      }
      document.body.appendChild(ghost);
      drag.ghost = ghost;
      // 持った対象は盤面から消える
      if (isFolder) render(state.icons, null, state.folders.filter(f => f.id !== drag.folderId));
      else render(state.icons, drag.iconId);
    }
    drag.ghost.style.left = e.clientX + 'px';
    drag.ghost.style.top = e.clientY + 'px';
    updateDragTarget(e.clientX, e.clientY);
  });

  function finishPointer(cancelled) {
    if (!drag) return;
    const wasActive = drag.active;
    const target = drag.target;
    const iconId = drag.iconId;
    const kind = drag.kind;
    const folderId = drag.folderId;
    const path = drag.path || [];
    const folderTarget = drag.folderTarget || null;
    const fromCell = { x: drag.fromX, y: drag.fromY };
    removeGhost();
    drag = null;
    if (!wasActive) {
      // 動かさずに離した = タップ（副操作）。選択／移動／フォルダ解除の処理へ回す
      if (!cancelled) handleTap(fromCell);
      return;
    }
    if (!cancelled && kind === 'folder' && target) {
      E.applyFolderMove(state, folderId, { x: target.x, y: target.y });
      render(state.icons, null);
    } else if (!cancelled && kind === 'icon' && (path.length || folderTarget)) {
      // 経路方式で確定する。フォルダ化の待機中に離せば、経路の手前まで
      // 進んで対象へ重なる（フォルダ化）。経路の途中で離せば、そこまでの
      // 入れ替えがそのまま結果になる
      E.applyPathMove(state, iconId, path, folderTarget);
      render(state.icons, null);
    } else {
      flipRender(state.icons, null); // 元の位置へ滑って戻る
    }
  }

  // 終了処理は、対象ポインターの主ボタンの解放だけに反応する。
  // 盤面とウィンドウの両方で受ける（二重に呼ばれても害はない作り）。
  function onPointerUp(e) {
    if (e.pointerType === 'mouse' && e.button !== 0) return; // 右ボタンの解放では終わらない
    if (drag) {
      if (e.pointerId !== drag.pointerId) return;
      press = null;
      finishPointer(false);
      return;
    }
    // ドラッグにならなかった押下（眠っているアイコン・空きマスなど）もタップとして扱う
    if (press && e.pointerId === press.pointerId) {
      const p = press;
      press = null;
      if (!p.handled && p.cell) handleTap(p.cell);
    }
  }
  function onPointerCancel(e) {
    if (drag && e.pointerId !== drag.pointerId) return;
    press = null;
    if (!drag) return;
    finishPointer(true);
  }
  boardEl.addEventListener('pointerup', onPointerUp);
  window.addEventListener('pointerup', onPointerUp);
  boardEl.addEventListener('pointercancel', onPointerCancel);
  window.addEventListener('pointercancel', onPointerCancel);

  // 終了の合図を取りこぼす経路への後始末：
  // ポインターキャプチャを失ったら、ドラッグを中断して表示を戻す
  boardEl.addEventListener('lostpointercapture', (e) => {
    if (drag && e.pointerId === drag.pointerId) cancelDrag();
  });
  // ウィンドウがフォーカスを失ったら中断する
  window.addEventListener('blur', () => { press = null; if (drag) cancelDrag(); });
  // 右クリックメニューは出さない（メニューが開くと離す操作が吸われてしまうため）。
  // ドラッグ中に盤面の外で出そうになった場合も、メニューを止めてドラッグを中断する
  boardEl.addEventListener('contextmenu', (e) => e.preventDefault());
  document.addEventListener('contextmenu', (e) => {
    if (drag) { e.preventDefault(); cancelDrag(); }
  });

  /* ==== タップ操作（副操作）：選択 → 行き先をタップで移動 ====
   * タップ側には選択肢を出さない（2026-11-10 ユーザー指定）。
   * 重ねる／入れ替えは自動判定のまま： applyMove の既定の解決
   * フォルダ版では、タップ側は入れ替え・移動のみ（フォルダ化はしない）。
   * 「重ねる／入れ替え」の分離はドラッグ操作でのみ行う */
  function selectIcon(iconId) {
    tapSel = iconId;
    render(state.icons, null);
  }

  function clearSelection() {
    tapSel = null;
    render(state.icons, null);
  }

  // タップ1回の処理。pos はタップされたマス
  function handleTap(pos) {
    if (state.status !== 'playing') return;
    // フォルダのマス: タップでフォルダが開く（スマホ準拠。中身が大きく
    // 表示され、中身をタップすると盤面へ出る。開く画面まわりは
    // openFolderSheet のコメントを参照）
    const folder = E.folderAt(state, pos.x, pos.y);
    if (folder) {
      tapSel = null;
      openFolderSheet(folder.id);
      return;
    }
    const icon = E.iconAt(state, pos.x, pos.y);
    if (tapSel) {
      const sel = state.icons.find(i => i.id === tapSel);
      if (!sel) { tapSel = null; render(state.icons, null); return; }
      if (icon && icon.id === tapSel) { clearSelection(); return; }
      if (icon) {
        // 相手のアイコンへ: 到達できれば入れ替えでそのまま移動する
        // （フォルダ版では、フォルダ化はドラッグの「重ねる」だけ。タップは自動判定）
        const reachable = E.destinations(state, tapSel, 'swap').some(d => d.x === pos.x && d.y === pos.y);
        if (reachable) {
          tapSel = null;
          E.applyMove(state, sel.id, { x: pos.x, y: pos.y, intent: 'swap' });
          render(state.icons, null);
          return;
        }
        // 届かない相手なら、動けるアイコンであれば選択をそちらへ移す
        if (icon.z === 0 && icon.mood !== 'rebel') { selectIcon(icon.id); return; }
        clearSelection();
        return;
      }
      // 空きマス: 移動先として成立すればそのまま移動する
      const dest = E.destinations(state, tapSel, 'swap').find(d => d.x === pos.x && d.y === pos.y);
      tapSel = null;
      if (dest) E.applyMove(state, sel.id, { x: pos.x, y: pos.y, intent: 'swap' });
      render(state.icons, null);
      return;
    }
    if (icon && icon.z === 0 && icon.mood !== 'rebel') selectIcon(icon.id);
  }

  // 壁紙：デフォルトはプリセット13番。プレイヤーは用意された壁紙か自分の写真を選べる。
  // 自分の写真は本人の端末のブラウザ内（localStorage）に小さく圧縮して保存するだけ。
  // サーバーへ送る経路はない（2026-11-09 ユーザー確認済みの仕様）
  /* ==== 壁紙プリセット（build-wallpapers.py が生成。手で編集しない） ==== */
  const WALLPAPER_PRESETS = [
    { id: 1, name: 'ゆる空', src: 'data:image/webp;base64,' },
    { id: 2, name: 'カラフル', src: 'data:image/webp;base64,' },
    { id: 3, name: '4色まる柄', src: 'data:image/webp;base64,' },
    { id: 4, name: '夜空', src: 'data:image/webp;base64,' },
    { id: 5, name: '虹と丘', src: 'data:image/webp;base64,' },
    { id: 6, name: '青海波', src: 'data:image/webp;base64,' },
    { id: 7, name: 'ゆめかわ', src: 'data:image/webp;base64,' },
    { id: 8, name: '森', src: 'data:image/webp;base64,' },
    { id: 9, name: 'サンセット', src: 'data:image/webp;base64,' },
    { id: 10, name: 'オーロラ', src: 'data:image/webp;base64,' },
    { id: 11, name: '桜', src: 'data:image/webp;base64,' },
    { id: 12, name: '海', src: 'data:image/webp;base64,' },
    { id: 13, name: 'プリズム', src: 'data:image/webp;base64,' },
    { id: 14, name: '猫', src: 'data:image/webp;base64,' },
    { id: 15, name: '紅葉', src: 'data:image/webp;base64,' },
    { id: 16, name: '銀河', src: 'data:image/webp;base64,' },
  ];
  /* ==== 壁紙プリセットここまで ==== */
  const DEFAULT_PRESET_ID = 13;
  const phoneEl = document.querySelector('.phone');
  const wallpaperInput = document.getElementById('wallpaperInput');
  const wallpaperSheet = document.getElementById('wallpaperSheet');
  const WALLPAPER_KEY = 'homeMerge.wallpaper.v1';

  // 保存形式: { kind: 'preset', id } | { kind: 'photo', data }
  // （旧形式＝dataURL文字列そのままの場合は写真として読み替える）
  function loadWallpaperState() {
    try {
      const raw = localStorage.getItem(WALLPAPER_KEY);
      if (!raw) return { kind: 'preset', id: DEFAULT_PRESET_ID };
      if (raw.startsWith('{')) {
        const p = JSON.parse(raw);
        if (p && p.kind === 'photo' && p.data) return p;
        if (p && p.kind === 'preset' && WALLPAPER_PRESETS.some(w => w.id === p.id)) return p;
      }
      return { kind: 'photo', data: raw };
    } catch (_) { return { kind: 'preset', id: DEFAULT_PRESET_ID }; }
  }
  let wallpaperState = loadWallpaperState();
  function wallpaperSrc() {
    if (wallpaperState.kind === 'photo') return wallpaperState.data;
    const p = WALLPAPER_PRESETS.find(w => w.id === wallpaperState.id) || WALLPAPER_PRESETS[0];
    return p ? p.src : '';
  }
  function saveWallpaperState() {
    try { localStorage.setItem(WALLPAPER_KEY, JSON.stringify(wallpaperState)); }
    catch (_) { /* 保存容量を超えたら、今回の表示だけに使う */ }
  }
  function applyWallpaper() {
    const src = wallpaperSrc();
    phoneEl.style.backgroundImage = src ? `url(${src})` : '';
    phoneEl.classList.toggle('has-wallpaper', !!src);
    if (src) updateStatusContrast(src);
    markCurrentPreset();
  }
  // 壁紙の上部（ステータスバー付近）の明るさを見て、ステータスバーの文字色を切り替える
  function updateStatusContrast(src) {
    const img = new Image();
    img.onload = () => {
      try {
        const c = document.createElement('canvas');
        c.width = 16; c.height = 16;
        const ctx = c.getContext('2d');
        const sh = Math.max(1, Math.floor(img.height * 0.12));
        ctx.drawImage(img, 0, 0, img.width, sh, 0, 0, 16, 16);
        const d = ctx.getImageData(0, 0, 16, 16).data;
        let lum = 0;
        for (let i = 0; i < d.length; i += 4) lum += 0.2126 * d[i] + 0.7152 * d[i + 1] + 0.0722 * d[i + 2];
        lum /= (d.length / 4) * 255;
        phoneEl.classList.toggle('wp-dark', lum < 0.55);
        phoneEl.classList.toggle('wp-light', lum >= 0.55);
      } catch (_) {
        phoneEl.classList.add('wp-dark');
        phoneEl.classList.remove('wp-light');
      }
    };
    img.src = src;
  }
  function markCurrentPreset() {
    document.querySelectorAll('.wallpaper-thumb').forEach(el => {
      el.classList.toggle('current',
        wallpaperState.kind === 'preset' && Number(el.dataset.presetId) === wallpaperState.id);
    });
  }
  function closeSheets() {
    wallpaperSheet.hidden = true;
    settingsSheet.hidden = true;
  }
  // プリセット一覧（サムネイル）を組み立てる
  document.getElementById('wallpaperGrid').innerHTML = WALLPAPER_PRESETS.map(p =>
    `<button class="wallpaper-thumb" type="button" data-preset-id="${p.id}"><img src="${p.src}" alt=""><span>${p.name}</span></button>`
  ).join('');
  document.querySelectorAll('.wallpaper-thumb').forEach(el => {
    el.addEventListener('click', () => {
      wallpaperState = { kind: 'preset', id: Number(el.dataset.presetId) };
      saveWallpaperState();
      applyWallpaper();
      closeSheets();
    });
  });
  document.getElementById('wallpaperPhotoBtn').addEventListener('click', () => wallpaperInput.click());
  document.getElementById('wallpaperDefaultBtn').addEventListener('click', () => {
    wallpaperState = { kind: 'preset', id: DEFAULT_PRESET_ID };
    try { localStorage.removeItem(WALLPAPER_KEY); } catch (_) { /* noop */ }
    applyWallpaper();
    closeSheets();
  });
  wallpaperInput.addEventListener('change', async () => {
    const file = wallpaperInput.files && wallpaperInput.files[0];
    wallpaperInput.value = '';
    if (!file) return;
    try {
      const dataUrl = await fileToWallpaperDataUrl(file);
      wallpaperState = { kind: 'photo', data: dataUrl };
      saveWallpaperState();
      applyWallpaper();
      closeSheets();
    } catch (_) { /* 読み込めない画像では何もしない */ }
  });
  async function fileToWallpaperDataUrl(file) {
    let bmp;
    if (window.createImageBitmap) {
      try { bmp = await createImageBitmap(file, { imageOrientation: 'from-image' }); }
      catch (_) { bmp = await createImageBitmap(file); }
    } else {
      bmp = await new Promise((res, rej) => {
        const img = new Image();
        img.onload = () => res(img);
        img.onerror = rej;
        img.src = URL.createObjectURL(file);
      });
    }
    const scale = Math.min(1, 900 / bmp.width, 1600 / bmp.height);
    const w = Math.max(1, Math.round(bmp.width * scale));
    const h = Math.max(1, Math.round(bmp.height * scale));
    const canvas = document.createElement('canvas');
    canvas.width = w; canvas.height = h;
    canvas.getContext('2d').drawImage(bmp, 0, 0, w, h);
    if (bmp.close) bmp.close();
    if (bmp instanceof HTMLImageElement) URL.revokeObjectURL(bmp.src);
    return canvas.toDataURL('image/jpeg', 0.82);
  }
  applyWallpaper();

  // フォルダを開く画面（スマホ準拠：タップでフォルダが画面いっぱいに
  // 開き、中身が実物大で並ぶ。背景はぼかして暗くする）。
  // - 中身をタップ → そのアイコンが盤面へ出る（取り出し。移動として
  //   数えない）。残り1個になると最後の1個も出てフォルダは消える
  // - パネルの外側をタップ → 閉じる（何も起きない）
  // 開いている間はシートが盤面全体を覆うので、盤面の操作は届かない
  const folderSheet = document.getElementById('folderSheet');
  const folderOpenGrid = document.getElementById('folderOpenGrid');
  const folderNameEl = document.getElementById('folderName');
  // フォルダ名はカテゴリで決まる（スマホでフォルダ名が付くのと同じ考え方）
  function folderDisplayName(folder) {
    const cat = folder.category;
    if (!cat) return '';
    if (cat.kind === 'type') return E.TYPES[cat.type].name;
    if (cat.kind === 'cross') return '十字';
    if (cat.kind === 'diagonal') return 'ナナメ';
    return '多様性';
  }
  function openFolderSheet(folderId) {
    openFolderId = folderId;
    renderFolderSheet();
    folderSheet.hidden = false;
  }
  function closeFolderSheet() {
    openFolderId = null;
    folderSheet.hidden = true;
  }
  function renderFolderSheet() {
    const folder = (state.folders || []).find(f => f.id === openFolderId);
    if (!folder) { closeFolderSheet(); return; }
    folderNameEl.textContent = folderDisplayName(folder);
    // 中身の大きさは盤面のマス実寸に合わせる（マスが container になり、
    // アイコンの cqw 寸法がそのまま効く）
    const cellRect = boardEl.querySelector('.cell').getBoundingClientRect();
    folderOpenGrid.innerHTML = '';
    for (const m of folder.members) {
      const item = document.createElement('button');
      item.type = 'button';
      item.className = 'folder-open-item';
      item.dataset.memberId = m.id;
      item.style.width = cellRect.width + 'px';
      item.style.height = cellRect.height + 'px';
      item.innerHTML = `<div class="icon-stack"><div class="app-icon ${E.TYPES[m.type].colorName} normal">${iconArtwork(E.TYPES[m.type])}</div></div>`;
      folderOpenGrid.appendChild(item);
    }
  }
  folderSheet.addEventListener('pointerdown', (e) => {
    if (!e.target.closest || !e.target.closest('.folder-panel')) closeFolderSheet();
  });
  folderOpenGrid.addEventListener('click', (e) => {
    const btn = e.target.closest && e.target.closest('.folder-open-item');
    if (!btn || openFolderId === null) return;
    const r = E.applyFolderExtract(state, openFolderId, Number(btn.dataset.memberId));
    if (!r.ok) return;
    render(state.icons, null);
    if (r.dissolved) closeFolderSheet();
    else renderFolderSheet();
  });

  // 設定アプリ：開くと項目が並び、「初期化」でゲームを最初からにする
  const settingsSheet = document.getElementById('settingsSheet');
  document.getElementById('wallpaperBtn').addEventListener('click', () => {
    wallpaperSheet.hidden = false;
  });
  document.getElementById('wallpaperBack').addEventListener('click', () => {
    wallpaperSheet.hidden = true;
  });
  boardEl.addEventListener('click', (e) => {
    if (e.target.closest && e.target.closest('.settings-app')) {
      settingsSheet.hidden = false;
    }
    if (e.target.closest && e.target.closest('.search-app')) {
      showSearchHome();
      searchSheet.hidden = false;
    }
  });

  // 検索アプリ：検索バーを押すと候補（遊び方／方向アイコン）が出て、
  // 候補を選ぶとそのページが開く
  const searchSheet = document.getElementById('searchSheet');
  const searchHome = document.getElementById('searchHome');
  const searchSuggestions = document.getElementById('searchSuggestions');
  const searchPages = { howto: document.getElementById('pageHowto'), icons: document.getElementById('pageIcons') };
  function showSearchHome() {
    searchHome.hidden = false;
    searchSuggestions.hidden = true;
    for (const p of Object.values(searchPages)) p.hidden = true;
  }
  document.getElementById('searchBack').addEventListener('click', () => {
    searchSheet.hidden = true;
  });
  document.getElementById('searchBar').addEventListener('click', () => {
    searchSuggestions.hidden = !searchSuggestions.hidden;
  });
  searchSheet.querySelectorAll('.suggestion').forEach(btn => {
    btn.addEventListener('click', () => {
      searchHome.hidden = true;
      for (const [key, p] of Object.entries(searchPages)) p.hidden = key !== btn.dataset.page;
    });
  });
  searchSheet.querySelectorAll('[data-back]').forEach(btn => {
    btn.addEventListener('click', showSearchHome);
  });
  // 方向アイコンの一覧（本物のアイコンの絵＋名前＋動ける方向）
  const ICON_DESCS = {
    tate: '上と下に動く', yoko: '左と右に動く',
    sayoku: '右上と左下に動く', uyoku: '左上と右下に動く',
  };
  document.getElementById('iconList').innerHTML = E.TYPE_IDS.map(id => {
    const t = E.TYPES[id];
    return `<div class="icon-row"><div class="icon-thumb"><div class="icon-stack"><div class="app-icon ${t.colorName} normal ${t.id}" style="--hop:1.6cqw">${iconArtwork(t)}</div></div></div>`
      + `<div><div class="icon-row-name">${t.name}</div><div class="icon-row-desc">${ICON_DESCS[id]}</div></div></div>`;
  }).join('');
  document.getElementById('settingsBack').addEventListener('click', () => {
    settingsSheet.hidden = true;
  });
  document.getElementById('initBtn').addEventListener('click', () => {
    resetWinOverlay();
    state = E.createGame();
    if (drag) { removeGhost(); drag = null; }
    press = null;
    tapSel = null;
    settingsSheet.hidden = true;
    searchSheet.hidden = true;
    wallpaperSheet.hidden = true;
    render(state.icons, null);
  });

  render(state.icons, null);
})();
